mkitem!{mkstruct!{# [doc = " Temporary data that gets initialized during a blocking operation, and is consumed by"] # [doc = " `read` or `write`."] # [doc = ""] # [doc = " Each field contains data associated with a specific channel flavor."] # [derive (Debug , Default)] pub struct Token { pub (crate) array : super :: array :: ArrayToken , pub (crate) list : super :: list :: ListToken , # [allow (dead_code)] pub (crate) zero : super :: zero :: ZeroToken , }}}
mkitem!{mkstruct!{# [doc = " Identifier associated with an operation by a specific thread on a specific channel."] # [derive (Debug , Clone , Copy , PartialEq , Eq)] pub struct Operation (usize) ;}}
mkitem!{mkimpl!{impl Operation { # [doc = " Creates an operation identifier from a mutable reference."] # [doc = ""] # [doc = " This function essentially just turns the address of the reference into a number. The"] # [doc = " reference should point to a variable that is specific to the thread and the operation,"] # [doc = " and is alive for the entire duration of a blocking operation."] # [inline] pub fn hook < T > (r : & mut T) -> Operation { let val = r as * mut T as usize ; assert ! (val > 2) ; Operation (val) } }}}
mkitem!{mkenum!{# [doc = " Current state of a blocking operation."] # [derive (Debug , Clone , Copy , PartialEq , Eq)] pub enum Selected { # [doc = " Still waiting for an operation."] Waiting , # [doc = " The attempt to block the current thread has been aborted."] Aborted , # [doc = " An operation became ready because a channel is disconnected."] Disconnected , # [doc = " An operation became ready because a message can be sent or received."] Operation (Operation) , }}}
mkitem!{mkimpl!{impl From < usize > for Selected { # [inline] fn from (val : usize) -> Selected { match val { 0 => Selected :: Waiting , 1 => Selected :: Aborted , 2 => Selected :: Disconnected , oper => Selected :: Operation (Operation (oper)) , } } }}}
mkitem!{mkimpl!{impl Into < usize > for Selected { # [inline] fn into (self) -> usize { match self { Selected :: Waiting => 0 , Selected :: Aborted => 1 , Selected :: Disconnected => 2 , Selected :: Operation (Operation (val)) => val , } } }}}